<!-- components/Stepper/Stepper.vue --><template>  <view class="stepper">    <!-- 具名插槽 prefix：不传就用默认减号 -->    <view class="btn" :class="{ disabled: inner <= min }"          @click="decrease">      <slot name="prefix">        <text class="btn-icon">-</text>      </slot>    </view>     <text class="count">{{ inner }}</text>     <!-- 具名插槽 suffix：不传就用默认加号 -->    <view class="btn" :class="{ disabled: inner >= max }"          @click="increase">      <slot name="suffix">        <text class="btn-icon">+</text>      </slot>    </view>  </view></template>

<script setup>import { ref, watch } from 'vue' // ---------- 1. props：父传子，只读 ----------const props = defineProps({  initialValue: { type: Number, default: 0 },  min:          { type: Number, default: 0 },  max:          { type: Number, default: 99 },  step:         { type: Number, default: 1 }}) // ---------- 2. emit：子传父 ----------const emit = defineEmits(['change']) // ---------- 3. ⚠️ props 只读，拷贝到自己的 ref ----------const inner = ref(props.initialValue) // 父组件的 initialValue 变了，同步到 innerwatch(() => props.initialValue, (val) => {  inner.value = val})
// ---------- 4. 加减：先算新值，再 emit 通知父组件 ----------function increase() {  if (inner.value >= props.max) return  inner.value = Math.min(inner.value + props.step, props.max)  emit('change', inner.value)} function decrease() {  if (inner.value <= props.min) return  inner.value = Math.max(inner.value - props.step, props.min)  emit('change', inner.value)}</script>

